<section class="report-kpis report-kpis--reference" aria-label="Indicadores del período">
  <article><span class="report-kpis__icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 5h16v14H4zM4 14h5l2 3h2l2-3h5"/></svg></span><div><strong><?= (int) $summary['total'] ?></strong><b>Solicitudes recibidas</b><small>Registradas durante el período</small></div><?php if (($change = $percentChange((float) $summary['total'], (float) $previousTotal)) !== null): ?><span class="report-kpis__change"><?= $e($change) ?></span><?php endif; ?></article>
