  <article><span class="report-kpis__icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h6"/></svg></span><div><strong><?= $pending ?></strong><b>Pendientes al corte</b><small>Registradas durante el período</small></div></article>
  <article><span class="report-kpis__icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/></svg></span><div><strong><?= $averageResolution === null ? '—' : number_format($averageResolution / 86400, 1, ',', '') . ' días' ?></strong><b>Tiempo promedio de resolución</b><small><?= $resolutionCount > 0 ? 'De ' . $resolutionCount . ($resolutionCount === 1 ? ' solicitud con solución registrada' : ' solicitudes con solución registrada') : 'Sin soluciones con tiempo calculable' ?></small></div><?php if ($averageResolution !== null && $previousAverageResolution !== null && ($change = $percentChange($averageResolution, $previousAverageResolution)) !== null): ?><span class="report-kpis__change"><?= $e($change) ?></span><?php endif; ?></article>
